//! Closed direct event-name catalogs from installed SDK2025.2.3.30 runtime
//! types and its EClass-to-runtime mappings for8.3.27/8.5.1. These are the
//! actual nested FieldExtInfo exclusions, not a global event-name whitelist.
pub(super) fn field_extension_events(kind: &str, modern: bool) -> &'static [&'static str] {
    match (kind, modern) {
        ("InputField", _) => &[
            "AutoComplete",
            "ChoiceProcessing",
            "Clearing",
            "CommandGenerateProcessing",
            "Creating",
            "EditTextChange",
            "MultipleValueOpening",
            "MultipleValueURLProcessing",
            "MultipleValuesAdd",
            "MultipleValuesDelete",
            "Opening",
            "StartChoice",
            "StartListChoice",
            "TextEditEnd",
            "Tuning",
        ],
        ("CheckBoxField", _) => &[],
        ("LabelField", _) => &["Click", "URLProcessing"],
        ("RadioButtonField", _) => &[],
        ("HTMLDocumentField", _) => &[
            "AfterWrite",
            "BeforePrint",
            "BeforeWrite",
            "DocumentComplete",
            "OnClick",
        ],
        ("ProgressBarField", _) => &[],
        ("FormattedDocumentField", _) => &["AfterWrite", "BeforePrint", "BeforeWrite"],
        ("TextDocumentField", _) => &["AfterWrite", "BeforePrint", "BeforeWrite"],
        ("PictureField", _) => &["Click", "Drag", "DragCheck", "DragEnd", "DragStart"],
        ("SpreadsheetDocumentField", false) => &[
            "AdditionalDetailProcessing",
            "AfterWrite",
            "BeforePrint",
            "BeforeWrite",
            "DetailProcessing",
            "Drag",
            "DragCheck",
            "DragEnd",
            "DragStart",
            "OnActivate",
            "OnChangeAreaContent",
            "Selection",
            "URLProcessing",
        ],
        ("SpreadsheetDocumentField", true) => &[
            "AdditionalDetailProcessing",
            "AfterWrite",
            "BeforePrint",
            "BeforeWrite",
            "DetailProcessing",
            "Drag",
            "DragCheck",
            "DragEnd",
            "DragStart",
            "OnActivate",
            "OnChangeAreaContent",
            "OnGenerateToolTipText",
            "Selection",
            "URLProcessing",
        ],
        ("CalendarField", _) => &[
            "Drag",
            "DragCheck",
            "DragEnd",
            "DragStart",
            "OnActivateDate",
            "OnPeriodOutput",
            "Selection",
        ],
        ("TrackBarField", _) => &[],
        ("PeriodField", _) => &["Selection"],
        ("GraphicalSchemaField", _) => &[
            "AfterWrite",
            "BeforePrint",
            "BeforeWrite",
            "OnActivate",
            "Selection",
        ],
        ("ChartField", _) => &["DetailProcessing", "OnActivate", "OnValueEdit", "Selection"],
        ("GanttChartField", _) => &[
            "BeforeCollapse",
            "BeforeExpand",
            "DetailProcessing",
            "OnActivateInterval",
            "OnActivateValue",
            "OnIntervalEditEnd",
            "Selection",
        ],
        ("PDFDocumentField", _) => &["URLClick"],
        _ => &[],
    }
}
